/**
 * "May the shell reload now?" — the single decision table shared by every
 * clean-up-and-reload path (plan decision 7).
 *
 * The inline `window.__LINM_MAY_RELOAD__` in `src/index.ejs` implements the same
 * table in plain ES5; keep both in step. This file is the tested twin used by
 * `deployRecovery.ts` when the inline function is absent (local builds, tests).
 */

export const PROBE_TIMEOUT_MS = 4000;

export type ReloadDecision = 'go' | 'defer' | 'skip';

/** The offline scope `pathname` falls under, or null. `/m/` contains `/m/` and `/m/x`, not `/m` or `/mas`. */
export function offlineScopeOf(pathname: string, scopes: readonly string[]): string | null {
  if (!pathname || !scopes) return null;
  for (const scope of scopes) {
    if (typeof scope === 'string' && scope && pathname.indexOf(scope) === 0) return scope;
  }
  return null;
}

/**
 * The offline scope the document was LOADED under, or null. `declared` is
 * `window.__LINM_DOC_OFFLINE_SCOPE__` (set once by the HTML document: the scope, or '' for none);
 * when it is absent (older HTML, local builds, tests) the live path decides, as before.
 */
export function loadedOfflineScope(
  declared: unknown,
  pathname: string,
  scopes: readonly string[],
): string | null {
  if (typeof declared === 'string') return declared || null;
  return offlineScopeOf(pathname, scopes);
}

export type GuardDeps = {
  pathname: () => string;
  scopes: () => readonly string[];
  deferred: () => boolean; // window.__LINM_DEFER_RELOAD__ === true
  onLine: () => boolean;
  probe: () => Promise<boolean>; // GET /_manifest.json?linm-probe=1&_=<now>, cache 'no-store', 4 s limit; true when a response arrived
};

/** 'go' | 'defer' | 'skip'. Outside offline scopes: 'go' unless deferred ('defer'). Inside: deferred → 'defer'; !onLine → 'skip'; probe false → 'skip'; else 'go'. Never rejects. */
export async function mayReload(deps: GuardDeps): Promise<ReloadDecision> {
  try {
    if (deps.deferred()) return 'defer';
    if (!offlineScopeOf(deps.pathname(), deps.scopes())) return 'go';
    if (!deps.onLine()) return 'skip';
    const reachable = await deps.probe();
    // The user may have entered a form while the probe was in flight.
    if (deps.deferred()) return 'defer';
    return reachable ? 'go' : 'skip';
  } catch {
    // Inside a scope a failing check means "not sure we are online" → do not reload.
    return 'skip';
  }
}

/** Slow fallback tick while deferred (a page left visible forever still reloads eventually). */
export const DEFER_RECHECK_MS = 60000;

type VisibilityDoc = Pick<Document, 'addEventListener' | 'removeEventListener' | 'visibilityState'>;
type EventWin = Pick<Window, 'addEventListener' | 'removeEventListener'>;

/**
 * Ask `decide` until it stops saying 'defer', then call `done` once with 'go' or 'skip'.
 * While deferred (plan decision 7): re-ask when the document becomes hidden, on `pagehide`
 * (navigation), and on a slow DEFER_RECHECK_MS fallback tick; never two questions in flight.
 */
export function awaitReloadDecision(
  decide: () => Promise<ReloadDecision>,
  done: (decision: 'go' | 'skip') => void,
  doc: VisibilityDoc = document,
  win: EventWin = window,
  recheckMs: number = DEFER_RECHECK_MS,
): void {
  const onPageHide = () => evaluate();
  let busy = false;
  let finished = false;
  let timer: ReturnType<typeof setInterval> | null = null;
  const onVisibility = () => {
    if (doc.visibilityState === 'hidden') evaluate();
  };
  const stop = () => {
    if (timer !== null) clearInterval(timer);
    timer = null;
    doc.removeEventListener('visibilitychange', onVisibility);
    win.removeEventListener('pagehide', onPageHide);
  };
  function evaluate(): void {
    if (busy || finished) return;
    busy = true;
    let p: Promise<ReloadDecision>;
    try {
      p = Promise.resolve(decide());
    } catch {
      p = Promise.resolve<ReloadDecision>('skip');
    }
    p.then(
      (d) => d,
      (): ReloadDecision => 'skip',
    ).then((d) => {
      busy = false;
      if (finished) return;
      if (d === 'defer') {
        if (timer === null) {
          timer = setInterval(evaluate, recheckMs);
          doc.addEventListener('visibilitychange', onVisibility);
          win.addEventListener('pagehide', onPageHide);
        }
        return;
      }
      finished = true;
      stop();
      done(d);
    });
  }
  evaluate();
}

export type GuardedReloadOptions = {
  decide: () => Promise<ReloadDecision>;
  deferred: () => boolean; // re-checked immediately before reloading
  delayMs: number;
  /** First 'go' only: count the reload; false (cap reached) abandons it. */
  onGo: () => boolean;
  onSkip: () => void;
  reload: () => void;
  doc?: VisibilityDoc;
  win?: EventWin;
};

/**
 * Guarded reload: wait for the decision, count it once, reload after `delayMs` — unless the
 * defer flag became true during the delay, in which case go back into the defer loop.
 */
export function runGuardedReload(opts: GuardedReloadOptions): void {
  let counted = false;
  const start = (): void => {
    awaitReloadDecision(
      opts.decide,
      (decision) => {
        if (decision === 'skip') {
          opts.onSkip();
          return;
        }
        if (!counted) {
          if (!opts.onGo()) return;
          counted = true;
        }
        setTimeout(() => {
          if (opts.deferred()) {
            start();
            return;
          }
          opts.reload();
        }, opts.delayMs);
      },
      opts.doc,
      opts.win,
    );
  };
  start();
}

type ProbeFetch = (url: string, init: RequestInit) => Promise<unknown>;

/** True when the probe request got any response within PROBE_TIMEOUT_MS. Never rejects. */
export function probeManifest(
  fetchFn: ProbeFetch,
  now: () => number = Date.now,
  timeoutMs: number = PROBE_TIMEOUT_MS,
): Promise<boolean> {
  return new Promise<boolean>((resolve) => {
    let settled = false;
    const finish = (value: boolean) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(value);
    };
    const timer = setTimeout(() => finish(false), timeoutMs);
    try {
      fetchFn(`/_manifest.json?linm-probe=1&_=${now()}`, { cache: 'no-store' }).then(
        () => finish(true),
        () => finish(false),
      );
    } catch {
      finish(false);
    }
  });
}
