/**
 * SSOT: @linm-soft-org/linm-web-common-components/src/services/authFetchInterceptor.ts
 * Root-only: network-failed refresh keeps the session inside offline scopes (2026-11-28) — carry to common-components at the next sync.
 */
import {
  AUTH_FETCH_SKIP_REFRESH_HEADER,
  buildRetryRequestInit,
  getAuthTokenForRetry,
  isAuthSelfRequestUrl,
  lastRefreshResult,
  armPreemptiveAuthRefresh,
  redirectToLoginAfterAuthFailure,
  requestHadBearerAuth,
  setAuthRefreshNativeFetch,
  tryRefreshToken,
} from './authTokenRefresh';
import { getActiveCompanyCode } from './activeCompanyStorage';
import { X_COMPANY_ID_HEADER } from './companyRequestHeaders';
import { rewriteForcedBffFetchUrl } from '../configuration/forceBffDomain';
import { getOrCreateBrowserDeviceId } from './browserDeviceId';
import { afterRefresh } from './refreshOutcome';
import { loadedOfflineScope } from '../offline/reloadGuard';

declare global {
  interface Window {
    __LINM_AUTH_FETCH_PATCHED__?: boolean;
  }
}

function resolveRequestUrl(input: RequestInfo | URL): string {
  if (typeof input === 'string') return input;
  if (input instanceof URL) return input.href;
  return input.url;
}

type ApiEnv = { VITE_API_URL?: string; VITE_MOBILE_API_URL?: string };

function hostOf(raw: unknown): string {
  if (typeof raw !== 'string' || !raw.trim()) return '';
  try {
    return new URL(raw.trim(), window.location.href).hostname.toLowerCase();
  } catch {
    return '';
  }
}

/** Hosts from the manifest / BFF base for this deployment. No product domain list. */
function configuredApiHosts(): Set<string> {
  const hosts = new Set<string>();
  const add = (raw: unknown) => {
    const host = hostOf(raw);
    if (host) hosts.add(host);
  };
  add(window.__LINM_AUTH_BFF_BASE__);
  add(window.__LINM_AUTH_BFF_BUILD__);
  add(window.__LINM_RUNTIME_ENV__?.VITE_API_URL);
  add(window.__LINM_MF_MANIFEST__?.env?.VITE_API_URL);
  const apps = window.__LINM_MF_MANIFEST__?.microfrontends;
  if (apps) {
    for (const entry of Object.values(apps)) {
      const env = entry?.env as ApiEnv | undefined;
      add(env?.VITE_API_URL);
      add(env?.VITE_MOBILE_API_URL);
    }
  }
  return hosts;
}

/** Device id stays on this site's API. A custom header on another host forces OPTIONS. */
function shouldAttachDeviceHeader(url: string): boolean {
  if (!url || url.startsWith('data:') || url.startsWith('blob:')) return false;
  let parsed: URL;
  try {
    parsed = new URL(url, window.location.href);
  } catch {
    return false;
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return false;
  if (parsed.origin === window.location.origin) return true;
  const host = parsed.hostname.toLowerCase();
  if (host === 'localhost' || host === '127.0.0.1') return true;
  return configuredApiHosts().has(host);
}

export function installAuthFetchInterceptor(): void {
  if (typeof window === 'undefined') return;
  if (window.__LINM_AUTH_FETCH_PATCHED__) return;

  const nativeFetch = window.fetch.bind(window);
  setAuthRefreshNativeFetch(nativeFetch);
  window.__LINM_AUTH_FETCH_PATCHED__ = true;

  window.fetch = async (input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    const rawUrl = resolveRequestUrl(input);
    const url = rewriteForcedBffFetchUrl(rawUrl);
    if (url !== rawUrl) {
      if (input instanceof Request) {
        input = new Request(url, input);
      } else {
        input = url;
      }
    }

    if (shouldAttachDeviceHeader(url)) {
      const deviceHeaders = new Headers(
        init?.headers ?? (input instanceof Request ? input.headers : undefined),
      );
      const deviceId = getOrCreateBrowserDeviceId();
      if (deviceId) deviceHeaders.set('X-Device-Id', deviceId);
      if (input instanceof Request) {
        input = new Request(input, { headers: deviceHeaders });
      }
      init = { ...init, headers: deviceHeaders };
    }

    const skipHeaders = new Headers(
      init?.headers ?? (input instanceof Request ? input.headers : undefined),
    );
    if (skipHeaders.get(AUTH_FETCH_SKIP_REFRESH_HEADER) === '1') {
      skipHeaders.delete(AUTH_FETCH_SKIP_REFRESH_HEADER);
      return nativeFetch(input, { ...init, headers: skipHeaders });
    }

    if (isAuthSelfRequestUrl(url)) {
      return nativeFetch(input, init);
    }

    const response = await nativeFetch(input, init);
    if (response.status !== 401) return response;
    if (!requestHadBearerAuth(input, init)) return response;

    const refreshed = await tryRefreshToken();
    if (!refreshed) {
      // Applies to a document LOADED inside an offline scope (wherever it navigated since).
      const inOfflineScope =
        loadedOfflineScope(
          window.__LINM_DOC_OFFLINE_SCOPE__,
          window.location.pathname,
          window.__LINM_OFFLINE_SCOPES__ ?? [],
        ) !== null;
      if (afterRefresh(lastRefreshResult() ?? 'rejected', inOfflineScope) === 'keep-session') {
        return response;
      }
      redirectToLoginAfterAuthFailure();
      return response;
    }

    const newToken = getAuthTokenForRetry();
    if (!newToken) {
      redirectToLoginAfterAuthFailure();
      return response;
    }

    let retryResponse: Response;
    if (input instanceof Request) {
      const headers = new Headers(input.headers);
      if (init?.headers) {
        new Headers(init.headers).forEach((value, key) => headers.set(key, value));
      }
      headers.set('Authorization', `Bearer ${newToken}`);
      const activeCompanyCode = getActiveCompanyCode();
      if (activeCompanyCode) headers.set(X_COMPANY_ID_HEADER, activeCompanyCode);
      retryResponse = await nativeFetch(new Request(input, { headers }));
    } else {
      retryResponse = await nativeFetch(input, buildRetryRequestInit(input, init, newToken));
    }

    if (retryResponse.status === 401) {
      redirectToLoginAfterAuthFailure();
    }
    return retryResponse;
  };

  armPreemptiveAuthRefresh();
}
